  "test_path": "tests/unit/test_observe_capture_error.py",
  "test": "import pytest
from langfuse import observe
from langfuse._client.attributes import LangfuseOtelSpanAttributes


def _finished_spans_by_name(memory_exporter, name):
    return [span for span in memory_exporter.get_finished_spans() if span.name == name]

def test_capture_error_false_does_not_record_error(langfuse_memory_client, memory_exporter):
    @observe(name="error_no_capture", capture_error=False)
    def bad_func():
        raise ValueError("oops")

    with pytest.raises(ValueError):
        bad_func()

    # Flush to ensure spans are exported
    langfuse_memory_client.flush()

    spans = _finished_spans_by_name(memory_exporter, "error_no_capture")
    assert len(spans) == 1
    span = spans[0]
    attrs = span.attributes
    # The observation level should not be set to ERROR when capture_error is False
    assert attrs.get(LangfuseOtelSpanAttributes.OBSERVATION_LEVEL) != "ERROR"
